#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""Verification command runner for synaptory hooks.

After receipt validation passes, re-runs verification_commands from the receipt
to confirm they still pass. Used by synaptory-verify-receipt.sh.

Issue #163: the allowlist / forbidden-token sets and every rejection message
are sourced from the evidence contract (core/lib/evidence_contract.py)
when it is importable; the embedded constants below are the degrade-gracefully
fallback so a partial install behaves exactly like the pre-contract runner.

Issue #164: validated commands are served from the replay cache
(core/lib/verification_cache.py) when the repo tree-state matches a
prior run; results served from cache carry `"cached": true`.

Issue #167: receipts that carry a `workspace_ref` pointing inside the managed
`.synaptory/.worktrees/` directory are replayed with that worktree as cwd.

Issue #168: `bash` / `sh` are only accepted with a repo-relative script that
exists inside the project — inline payloads (`-c`, `-s`, `-i`) are refused.

CLI: python3 verification_runner.py <receipt.json> <project_dir> [--replay-strict]
"""

# NFR-PLUGIN-2: Python 3.9+. Annotations below use PEP 604 unions
# (`X | None`); the future-import defers evaluation so 3.9 doesn't
# choke at module-load time.
from __future__ import annotations

import json
import os
import re
import shlex
import subprocess
import sys
from typing import Any

# Sibling modules (same hooks/lib dir). Optional by design: a missing module
# degrades to the embedded fallbacks (contract) or disables the feature
# entirely (cache) — the runner must keep working on partial installs.
try:  # pragma: no cover - import plumbing
    import evidence_contract as _evidence_contract  # type: ignore
except ImportError:  # pragma: no cover
    try:
        from hooks.lib import evidence_contract as _evidence_contract  # type: ignore
    except ImportError:
        _evidence_contract = None  # type: ignore[assignment]

try:  # pragma: no cover - import plumbing
    import verification_cache as _verification_cache  # type: ignore
except ImportError:  # pragma: no cover
    try:
        from hooks.lib import verification_cache as _verification_cache  # type: ignore
    except ImportError:
        _verification_cache = None  # type: ignore[assignment]

TOTAL_TIMEOUT = 300  # 5 minutes total
PER_COMMAND_TIMEOUT = 60  # 1 minute per command
STDOUT_SNIPPET_LENGTH = 500

# Allowlist of verification executables — EMBEDDED FALLBACK. The effective
# allowlist comes from the evidence contract (which adds test, grep, ls, wc,
# diff, jq, stat, head, tail, find); this constant is what a contract-less
# install degrades to. Receipts are agent-supplied and must be treated as
# untrusted input, so we refuse anything outside the effective set rather
# than interpreting shell metacharacters. See AST06-F1 in the agency audit.
VERIFICATION_ALLOWLIST = frozenset({
    # Python
    "python", "python3", "pytest", "ruff", "mypy", "pyright", "black", "flake8",
    # JS/TS
    "node", "npm", "npx", "pnpm", "yarn", "tsc", "eslint", "prettier", "vitest", "jest",
    # Go
    "go", "gofmt", "golangci-lint",
    # Rust
    "cargo", "rustc", "clippy",
    # Other ecosystems
    "make", "cmake", "ctest", "mvn", "gradle", "bundle", "rspec", "rake",
    # Shell / generic
    "bash", "sh", "shellcheck",
    # Repo-local verifications
    "./synaptory",
})

# Bare shell-control tokens that, if present as their own argv token, indicate
# the author expected shell=True composition. Metacharacters inside quoted
# arguments (e.g. `python3 -c 'import x; x.y()'`) are fine because with
# shell=False they are passed verbatim as a single argv string.
# EMBEDDED FALLBACK — the effective set comes from the contract.
_SHELL_CONTROL_TOKENS = frozenset({"|", "||", "&", "&&", ";", ">", ">>", "<", "<<"})

# find flags that execute or mutate — EMBEDDED FALLBACK for the contract's
# replayability.find_flag_denylist.
_FIND_FLAG_DENYLIST = frozenset({"-exec", "-execdir", "-ok", "-okdir", "-delete", "-fprintf"})

# Interpreter flags that smuggle inline scripts — EMBEDDED FALLBACK for the
# contract's replayability.interpreter_flag_denylist. #170 review: receipts are
# untrusted input, so `python3 -c '…'` and `node -e '…'` are arbitrary code
# execution exactly like `bash -c` and get the same treatment. Module
# execution (`python3 -m <module>`, see _INTERPRETER_MODULE_OK) stays allowed —
# it names an installed module, it is not an inline payload.
_INTERPRETER_FLAG_DENYLIST: dict[str, frozenset[str]] = {
    "bash": frozenset({"-c", "-s", "-i"}),
    "sh": frozenset({"-c", "-s", "-i"}),
    "python": frozenset({"-c"}),
    "python3": frozenset({"-c"}),
    "node": frozenset({"-e", "--eval", "-p", "--print"}),
}

# Interpreters that may run a named module (`-m <module>`) instead of a
# repo-relative script file — EMBEDDED FALLBACK for interpreter_module_ok.
_INTERPRETER_MODULE_OK = frozenset({"python", "python3"})

# Interpreters whose script argument must be a repo-relative file that exists
# inside the project (the strict #168 bash/sh regime) — EMBEDDED FALLBACK for
# interpreter_require_repo_relative_script. python/node get the inline-payload
# + absolute-path block but NOT this existence requirement, so first-class
# plugin invocations like `python3 ${PLUGIN_ROOT}/skills/.../x.py`
# stay valid.
_INTERPRETER_REQUIRE_REPO_RELATIVE = frozenset({"bash", "sh"})

# Env-var assignment prefix (`FOO=1 cmd ...`) — only works under a shell;
# with shell=False the runner would try to execute "FOO=1" as a program.
_ENV_PREFIX_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")


# ─── Contract plumbing ────────────────────────────────────────────────────────

_contract_cache: Any = None


def _contract() -> dict[str, Any] | None:
    """Lazily load the evidence contract once; None when unavailable."""
    global _contract_cache
    if _evidence_contract is None:
        return None
    if _contract_cache is None:
        try:
            _contract_cache = _evidence_contract.load_contract()
        except Exception:
            _contract_cache = False  # sentinel: tried and failed
    return _contract_cache if isinstance(_contract_cache, dict) else None


def _replayability() -> dict[str, Any]:
    c = _contract()
    if c is not None:
        block = c.get("verification_commands", {}).get("replayability", {})
        if isinstance(block, dict):
            return block
    return {}


def _effective_allowlist() -> frozenset[str]:
    values = _replayability().get("allowlist")
    if isinstance(values, list) and values:
        return frozenset(values)
    return VERIFICATION_ALLOWLIST


def _effective_shell_tokens() -> frozenset[str]:
    values = _replayability().get("forbidden_tokens")
    if isinstance(values, list) and values:
        return frozenset(values)
    return _SHELL_CONTROL_TOKENS


def _effective_find_denylist() -> frozenset[str]:
    values = _replayability().get("find_flag_denylist")
    if isinstance(values, list) and values:
        return frozenset(values)
    return _FIND_FLAG_DENYLIST


def _effective_interpreter_denylist() -> dict[str, frozenset[str]]:
    values = _replayability().get("interpreter_flag_denylist")
    if isinstance(values, dict) and values:
        return {k: frozenset(v) for k, v in values.items() if isinstance(v, list)}
    return _INTERPRETER_FLAG_DENYLIST


def _effective_interpreter_module_ok() -> frozenset[str]:
    values = _replayability().get("interpreter_module_ok")
    if isinstance(values, list) and values:
        return frozenset(values)
    return _INTERPRETER_MODULE_OK


def _effective_interpreter_repo_relative() -> frozenset[str]:
    values = _replayability().get("interpreter_require_repo_relative_script")
    if isinstance(values, list) and values:
        return frozenset(values)
    return _INTERPRETER_REQUIRE_REPO_RELATIVE


def _explain(code: str, fallback: str, **ctx: Any) -> str:
    """Short machine-greppable reason + the contract's self-explaining fix.

    The short fallback string is kept as the prefix so existing consumers
    (and log greps) that match on it keep working; the contract explanation
    (which ends with the concrete fix) is appended when available.
    """
    if _evidence_contract is not None:
        try:
            return f"{fallback} — {_evidence_contract.explain_rejection(code, **ctx)}"
        except Exception:
            pass
    return fallback


# ─── Command validation ───────────────────────────────────────────────────────


def _validate_command(
    command: str, project_dir: str | None = None
) -> tuple[list[str] | None, str | None]:
    """Parse a verification command into argv; return (argv, error).

    On success: (argv, None) where argv[0] is in the effective allowlist.
    On refusal: (None, reason) — reason starts with a short greppable string
    and, when the evidence contract is available, continues with the
    canonical self-explaining rejection (ending in the concrete fix).

    `project_dir` (the cwd the command would run in) enables the #168
    existence check for bash/sh script arguments; path-shape checks
    (absolute / `..`) apply regardless.
    """
    if not isinstance(command, str) or not command.strip():
        return None, "empty or non-string command"
    try:
        argv = shlex.split(command, posix=True)
    except ValueError as e:
        return None, f"unparseable command: {e}"
    if not argv:
        return None, "empty argv after parse"
    # Reject command substitution and backtick expansion — shlex preserves these
    # as characters inside a token, so inspect every token.
    for tok in argv:
        if "$(" in tok or "`" in tok:
            return None, _explain(
                "command_substitution",
                "command substitution ($(...) or backticks) not permitted",
            )
    # Reject bare shell-control tokens (pipes, redirects, chaining).
    shell_tokens = _effective_shell_tokens()
    for tok in argv:
        if tok in shell_tokens:
            return None, _explain(
                "unreplayable_pipe",
                f"shell control token {tok!r} not permitted (use shell=False-safe commands)",
            )
    # Reject env-var assignment prefixes (`FOO=1 cmd`) — shell-only construct.
    if _ENV_PREFIX_RE.match(argv[0]):
        return None, _explain(
            "env_prefix",
            f"environment-variable prefix {argv[0]!r} not permitted (runner uses shell=False)",
        )
    program = os.path.basename(argv[0])
    allow = _effective_allowlist()
    # Allow local executables like ./synaptory via exact match on argv[0].
    if argv[0] not in allow and program not in allow:
        return None, _explain(
            "not_allowlisted",
            f"program '{argv[0]}' not in verification allowlist",
            program=argv[0],
        )
    # find hardening: refuse flags that execute or mutate (#163).
    if program == "find":
        deny = _effective_find_denylist()
        for tok in argv[1:]:
            if tok in deny:
                return None, _explain(
                    "find_forbidden_flag",
                    f"find flag {tok!r} not permitted",
                    flag=tok,
                )
    # Interpreter hardening (#168 + #170). See _validate_interpreter.
    if program in _effective_interpreter_denylist():
        err = _validate_interpreter(program, argv[1:], project_dir)
        if err:
            return None, err
    return argv, None


def _validate_interpreter(
    program: str, args: list[str], project_dir: str | None
) -> str | None:
    """Positionally validate an interpreter invocation; None if safe (#170).

    Receipts are untrusted input, so an interpreter must not be a vector for
    arbitrary code execution. Parse left-to-right the way the interpreter
    itself does — leading option flags, then the FIRST positional token is the
    script (everything after belongs to the script):

      * inline-code flags (`-c`, node `-e`/`--eval`/`-p`/`--print`, incl.
        `--flag=value` and node short clusters like `-pe`) → refused;
      * node loader/preload flags (`-r`/`--require`/`--import`/`--loader`/
        `--experimental-loader`) → refused: they run an external module
        BEFORE the script;
      * `-` (script from stdin) → refused;
      * `-m <module>` → allowed for module_ok interpreters, but ONLY when it
        is reached before any positional script (so `python3 /abs.py -m x`,
        which actually runs /abs.py, is caught by the script check first —
        the #170 re-review bypass);
      * the first positional token is the script: an absolute path is refused
        for every interpreter, and bash/sh additionally require a
        repo-relative path that exists inside the project.
    """
    deny = _effective_interpreter_denylist().get(program, frozenset())
    module_ok = program in _effective_interpreter_module_ok()
    require_repo = program in _effective_interpreter_repo_relative()

    for tok in args:
        flag = tok.split("=", 1)[0]  # catches `--require=/x`, `--loader=./e`
        if flag in deny:
            return _explain(
                "interpreter_inline",
                f"interpreter flag {tok!r} not permitted for {program} "
                "(inline code or module preload)",
            )
        # node short clusters: `-pe` / `-ep` smuggle eval/print.
        if (
            program == "node"
            and tok.startswith("-")
            and not tok.startswith("--")
            and len(tok) > 1
            and set(tok[1:]) & {"e", "p"}
        ):
            return _explain(
                "interpreter_inline",
                f"inline eval/print flag {tok!r} not permitted for node",
            )
        if tok == "-":
            return _explain(
                "interpreter_inline",
                f"{program} reading a script from stdin ('-') not permitted",
            )
        if tok == "-m" and module_ok:
            return None  # module mode, reached before any positional script
        if not tok.startswith("-"):
            return _validate_interpreter_script(tok, program, project_dir, require_repo)
        # else: an interpreter option we don't act on — skip, keep scanning.
    return _explain(
        "interpreter_inline", f"{program} requires a script argument"
    )


def _validate_interpreter_script(
    script: str, program: str, project_dir: str | None, require_repo: bool
) -> str | None:
    """Validate the resolved script-path token; None if safe."""
    # An absolute script path is refused for EVERY interpreter — a receipt
    # must not point the replay at an out-of-tree file.
    if os.path.isabs(script):
        return _explain(
            "interpreter_inline",
            f"interpreter script must be repo-relative, got absolute path {script!r}",
        )
    # The strict bash/sh regime (#168) additionally forbids `..` traversal and
    # requires the script to exist inside the project. python/node keep
    # first-class plugin invocations (`python3 ${PLUGIN_ROOT}/x.py`), so
    # they get the inline-payload + absolute-path block only.
    if require_repo:
        if ".." in script.replace("\\", "/").split("/"):
            return _explain(
                "interpreter_inline",
                f"interpreter script path {script!r} must not contain '..' segments",
            )
        if project_dir:
            base = os.path.realpath(project_dir)
            full = os.path.realpath(os.path.join(base, script))
            try:
                inside = os.path.commonpath([base, full]) == base
            except ValueError:
                inside = False
            if not inside or not os.path.isfile(full):
                return _explain(
                    "interpreter_inline",
                    f"interpreter script {script!r} not found inside the project",
                )
    return None


# ─── Config (.synaptory.yaml quality.verification.*) ─────────────────────────


def _read_verification_config(project_dir: str) -> dict[str, bool]:
    """Tiny line-scanner for `.synaptory.yaml` → quality.verification.{keys}.

    Recognises `replay_strict` and `replay_cache` booleans. Deliberately not
    a YAML parser (no dependency budget in hooks); mirrors the flat scanners
    used elsewhere in the hook tree. Missing file / keys → {}.
    """
    out: dict[str, bool] = {}
    path = os.path.join(project_dir, ".synaptory.yaml")
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.read().splitlines()
    except OSError:
        return out
    in_quality = False
    in_verification = False
    verification_indent = -1
    for raw in lines:
        line = raw.split("#", 1)[0].rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        stripped = line.strip()
        if indent == 0:
            in_quality = stripped == "quality:" or stripped.startswith("quality:")
            in_verification = False
            continue
        if not in_quality:
            continue
        if not in_verification:
            if stripped == "verification:" or stripped.startswith("verification:"):
                in_verification = True
                verification_indent = indent
            continue
        if indent <= verification_indent:
            # Left the verification block (sibling key under quality:).
            in_verification = stripped.startswith("verification:")
            continue
        key, sep, value = stripped.partition(":")
        if not sep:
            continue
        key = key.strip()
        value = value.strip().strip('"').strip("'").lower()
        if key in ("replay_strict", "replay_cache") and value in (
            "true", "false", "yes", "no", "1", "0", "on", "off",
        ):
            out[key] = value in ("true", "yes", "1", "on")
    return out


# ─── workspace_ref resolution (#167) ─────────────────────────────────────────

_WORKTREES_RELDIR = os.path.join(".synaptory", ".worktrees")


def _resolve_workspace_cwd(workspace_ref: Any, project_dir: str) -> str | None:
    """Resolve a receipt's workspace_ref to a replay cwd, or None.

    Accepts both shapes:
      * dict  — {"ref": "wt://synaptory/US-1", "path": "/abs/path"}
      * str   — "wt://synaptory/US-1" (path derived as
                <project_dir>/.synaptory/.worktrees/<story-id-from-ref>)

    The resolved path must exist and (after realpath) live under the managed
    <project_dir>/.synaptory/.worktrees/ directory — anything else (escape
    attempt, stale ref, foreign path) falls back to project_dir (None).
    """
    candidate: str | None = None
    if isinstance(workspace_ref, dict):
        path = workspace_ref.get("path")
        if isinstance(path, str) and path.strip():
            candidate = path
    elif isinstance(workspace_ref, str) and workspace_ref.startswith("wt://"):
        story_id = workspace_ref[len("wt://"):].rstrip("/").rsplit("/", 1)[-1]
        if story_id:
            candidate = os.path.join(project_dir, _WORKTREES_RELDIR, story_id)
    if not candidate:
        return None
    if not os.path.isabs(candidate):
        candidate = os.path.join(project_dir, candidate)
    if not os.path.isdir(candidate):
        return None
    base = os.path.realpath(os.path.join(project_dir, _WORKTREES_RELDIR))
    resolved = os.path.realpath(candidate)
    try:
        if os.path.commonpath([base, resolved]) != base or resolved == base:
            return None
    except ValueError:
        return None
    return resolved


# ─── Result type ──────────────────────────────────────────────────────────────


class VerificationResult:
    """Result of running verification commands."""

    def __init__(self) -> None:
        self.skipped = False
        self.passed = True
        self.results: list[dict[str, Any]] = []
        self.failures: list[dict[str, Any]] = []

    def to_dict(self) -> dict[str, Any]:
        return {
            "skipped": self.skipped,
            "passed": self.passed,
            "total": len(self.results),
            "failures": self.failures,
            "results": self.results,
        }


# ─── Runner ───────────────────────────────────────────────────────────────────


def run_verifications(
    receipt_path: str,
    project_dir: str,
    per_command_timeout: int = PER_COMMAND_TIMEOUT,
    replay_strict: bool | None = None,
    replay_cache: bool | None = None,
) -> VerificationResult:
    """Re-run verification commands from a receipt.

    Args:
        receipt_path: Path to receipt JSON file.
        project_dir: Project root (default cwd for commands; overridden by a
            valid receipt `workspace_ref` — see _resolve_workspace_cwd).
        per_command_timeout: Timeout per command in seconds.
        replay_strict: When True, an executed-object entry (dict with a
            recorded exit_code) whose command fails validation is a hard
            failure. Default (None) reads `.synaptory.yaml`
            quality.verification.replay_strict, falling back to False —
            unreplayable executed proof is then marked
            `{"replayed": false, "reason": ...}` (warning-level, REQ-E-003:
            marked, not silently accepted) and the recorded exit_code remains
            the DoD evidence. Declared string commands always fail hard on
            rejection.
        replay_cache: When True, serve validated commands from the replay
            cache (#164) when the tree state matches; results carry
            `"cached": true`. Only PASSING runs are stored (a cached failure
            would pin transient-environment flakes until the tree changes);
            a served entry is honoured as-is either way. Default (None)
            reads quality.verification.replay_cache, falling back to ENABLED.

    Returns:
        VerificationResult with pass/fail per command.
    """
    result = VerificationResult()

    # Parse receipt
    try:
        with open(receipt_path, "r") as f:
            receipt = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        result.skipped = True
        return result
    if not isinstance(receipt, dict):
        result.skipped = True
        return result

    # Check for verification_commands — required since SDD enforcement
    commands = receipt.get("verification_commands")
    if not commands or not isinstance(commands, list):
        result.skipped = True
        result.passed = False  # Missing verification_commands is a failure, not a pass
        return result

    # Resolve config-driven behaviour (explicit params win over .synaptory.yaml).
    if replay_strict is None or replay_cache is None:
        cfg = _read_verification_config(project_dir)
        if replay_strict is None:
            replay_strict = cfg.get("replay_strict", False)
        if replay_cache is None:
            replay_cache = cfg.get("replay_cache", True)

    # #167: replay inside the story worktree when the receipt says the work
    # happened there — otherwise the commands verify the wrong tree.
    run_cwd = _resolve_workspace_cwd(receipt.get("workspace_ref"), project_dir) or project_dir

    cache_enabled = bool(replay_cache) and _verification_cache is not None

    for cmd_entry in commands:
        executed_form = isinstance(cmd_entry, dict)
        if executed_form:
            if "command" not in cmd_entry:
                continue
            command = cmd_entry["command"]
            expected_exit = cmd_entry.get("exit_code", 0)
        elif isinstance(cmd_entry, str):
            # Declared form: a replay instruction — the contract's stated
            # purpose of string entries is that this hook re-runs them.
            command = cmd_entry
            expected_exit = 0
        else:
            continue

        entry: dict[str, Any] = {
            "command": command,
            "expected_exit_code": expected_exit,
        }

        argv, reject_reason = _validate_command(command, project_dir=run_cwd)
        if argv is None:
            if executed_form and not replay_strict:
                # REQ-E-003: an already-executed proof whose command can't be
                # replayed is MARKED, not silently accepted — and not failed:
                # the recorded exit_code remains the DoD evidence. Strict mode
                # (quality.verification.replay_strict) restores the hard fail.
                entry["replayed"] = False
                entry["reason"] = reject_reason
                entry["passed"] = None
                result.results.append(entry)
                continue
            entry["actual_exit_code"] = -1
            entry["stdout_snippet"] = ""
            entry["stderr_snippet"] = f"verification command rejected: {reject_reason}"
            entry["passed"] = False
            result.passed = False
            result.failures.append(entry)
            result.results.append(entry)
            continue

        # #164: replay cache — identical command at an identical tree state is
        # served from disk. Keyed on run_cwd so worktree replays don't collide
        # with root-tree replays.
        if cache_enabled:
            try:
                cached = _verification_cache.lookup(run_cwd, command)
            except Exception:
                cached = None
            if isinstance(cached, dict) and isinstance(cached.get("actual_exit_code"), int):
                entry["actual_exit_code"] = cached["actual_exit_code"]
                entry["stdout_snippet"] = cached.get("stdout_snippet", "")
                entry["stderr_snippet"] = cached.get("stderr_snippet", "")
                entry["cached"] = True
                entry["passed"] = entry["actual_exit_code"] == expected_exit
                if not entry["passed"]:
                    result.passed = False
                    result.failures.append(entry)
                result.results.append(entry)
                continue

        try:
            proc = subprocess.run(
                argv,
                shell=False,
                cwd=run_cwd,
                timeout=per_command_timeout,
                capture_output=True,
                text=True,
            )
            entry["actual_exit_code"] = proc.returncode
            entry["stdout_snippet"] = proc.stdout[:STDOUT_SNIPPET_LENGTH] if proc.stdout else ""
            entry["stderr_snippet"] = proc.stderr[:STDOUT_SNIPPET_LENGTH] if proc.stderr else ""
            entry["passed"] = proc.returncode == expected_exit

            if not entry["passed"]:
                result.passed = False
                result.failures.append(entry)

            # Cache PASSING runs only. A failure may be transient environment
            # (port in use, flaky service) — caching it would pin the failure
            # for every retry until the tree changes, blocking re-dispatches
            # that fix the environment without touching files. Failing
            # commands are cheap to re-run; passing ones are the 50×-repeat
            # cost #164 targets. Timeouts/exceptions are likewise not cached.
            if cache_enabled and entry["passed"]:
                try:
                    _verification_cache.store(
                        run_cwd,
                        command,
                        {
                            "actual_exit_code": proc.returncode,
                            "stdout_snippet": entry["stdout_snippet"],
                            "stderr_snippet": entry["stderr_snippet"],
                        },
                    )
                except Exception:
                    pass

        except subprocess.TimeoutExpired:
            entry["actual_exit_code"] = -1
            entry["stdout_snippet"] = ""
            entry["stderr_snippet"] = f"Command timed out after {per_command_timeout}s"
            entry["passed"] = False
            result.passed = False
            result.failures.append(entry)

        except Exception as e:
            entry["actual_exit_code"] = -1
            entry["stdout_snippet"] = ""
            entry["stderr_snippet"] = str(e)
            entry["passed"] = False
            result.passed = False
            result.failures.append(entry)

        result.results.append(entry)

    return result


if __name__ == "__main__":
    flags = [a for a in sys.argv[1:] if a.startswith("--")]
    positional = [a for a in sys.argv[1:] if not a.startswith("--")]
    if len(positional) < 2:
        print(
            f"Usage: {sys.argv[0]} <receipt.json> <project_dir> [--replay-strict]",
            file=sys.stderr,
        )
        sys.exit(1)

    receipt_path = positional[0]
    project_dir = positional[1]
    res = run_verifications(
        receipt_path,
        project_dir,
        replay_strict=True if "--replay-strict" in flags else None,
        replay_cache=False if "--no-replay-cache" in flags else None,
    )
    print(json.dumps(res.to_dict(), indent=2))
    sys.exit(0 if res.passed else 1)
